import {CODE_LIBRARY,searchCodes} from './code-library.js';
import {loadLocalCodes,searchLocalCodes} from './local-search.js';
const $=s=>document.querySelector(s);
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const safe=url=>/^https:\/\//.test(url||'')?url:'#';
export function setupCodeLibrary({getViewer,onSelectCode,onAskAI,notify}){
 let mode='local',chosen=null,shown=[],timer,sequence=0;
 const dialog=$('#libraryDialog'),search=$('#librarySearch'),results=$('#libraryResults'),preview=$('#libraryPreview');
 function choose(item){chosen=item;const local=mode==='local';const anchor=item.anchor||'';preview.innerHTML=`<div class="eyebrow">${local?'LOCAL PDF EVIDENCE · 本地规范原文':'SOURCE-LINKED CLAUSE · 条款依据'}</div><h3>${esc(local?item.title:item.title.en)}${!local?`<small>${esc(item.title.zh)}</small>`:''}</h3><div class="library-source-tag">${local?`${esc(item.docId)} · ${esc(item.agency)} · PDF p.${item.page}`:`SCDF §${esc(item.clause)}`}</div>${local?`<blockquote>${esc(item.excerpt)}</blockquote><p class="library-note">${esc(item.versionNote||"")}<br>Extracted PDF text; check the complete page and applicability.<br>PDF 提取原文；须结合完整页面和适用条件核对。</p>`:`<p>${esc(item.summary.en)}<small>${esc(item.summary.zh)}</small></p><p>${esc(item.requirements.en)}<small>${esc(item.requirements.zh)}</small></p>`}<a href="${safe(local?(item.pdfUrl||item.officialUrl):item.sourceUrl)}${local&&item.pdfUrl?'#page='+item.page:''}" target="_blank" rel="noopener">Open source / 查看来源 ↗</a><div class="library-binding"><label for="codeAnchor">Relevant model region / 关联模型区域</label><select id="codeAnchor"><option value="">Unmapped / 待定位</option><option value="road">Access road / 消防通道</option><option value="canopy">Canopy / 雨棚</option><option value="entry">Entrance / 入口</option><option value="building">Building / 建筑本体</option></select><small>Conceptual sample-region link; dimensional evidence is still required.<br>关联示例模型区域；尺寸证据仍需补充。</small></div><button class="primary full" id="markLibraryCode">Mark in model / 在模型中标记 ↗</button><button class="outline full" id="explainLibraryCode">Ask GPT-6.1 / 解读此片段 →</button>`;$('#codeAnchor').value=anchor;$('#markLibraryCode').onclick=()=>mark(false);$('#explainLibraryCode').onclick=()=>mark(true);[...results.querySelectorAll('[data-code-index]')].forEach(b=>b.classList.toggle('selected',shown[Number(b.dataset.codeIndex)]===item));}
 function asCode(){if(!chosen)return null;if(mode==='local')return {id:chosen.id,clause:`${chosen.docId} · PDF p.${chosen.page}`,title:{en:chosen.title,zh:'本地规范检索片段'},summary:{en:chosen.excerpt,zh:'基于本地 PDF 的原文检索结果；适用性待核实。'},requirements:{en:'Review the complete page, definitions and project applicability.',zh:'核对完整页面、定义及项目适用条件。'},requiredInputs:['Project scope / 项目条件','Verified dimensions / 核实尺寸'],sourceUrl:chosen.pdfUrl||chosen.officialUrl,page:chosen.page,docId:chosen.docId,status:'candidate',anchor:$('#codeAnchor').value||null,sourceType:'local-pdf',versionNote:chosen.versionNote,sourceChecked:chosen.sourceChecked};return {...chosen,anchor:$('#codeAnchor').value||null};}
 function mark(ask){const code=asCode();if(!code)return;const outcome=getViewer()?.markCode(code);onSelectCode(code,outcome);dialog.close();notify(outcome?.located?'Source linked to the selected sample region. / 已关联到示例模型区域。':'Source selected; model location needs confirmation. / 已选择依据，模型位置待确认。');if(ask)onAskAI();}
 async function run(){const token=++sequence;results.innerHTML='<p class="library-loading">Searching source text… / 正在检索规范原文…</p>';try{if(mode==='local'){const found=await searchLocalCodes(search.value,{agency:$('#libraryAgency').value,limit:12});if(token!==sequence)return;shown=found.results;$('#libraryStats').textContent=`${found.documentCount} PDFs · ${found.pageCount.toLocaleString()} pages · ${shown.length} results / 份规范 · 页 · 条结果`;results.innerHTML=shown.map((r,i)=>`<button class="library-result" data-code-index="${i}"><span>${esc(r.agency)} · ${esc(r.docId)} · PDF p.${r.page}</span><strong>${esc(r.title)}</strong><p>${esc(r.excerpt.slice(0,240))}…</p></button>`).join('')||'<p class="library-loading">No text match. Try an English keyword or another authority.<br>未找到原文匹配，请尝试英文关键词或其他主管机构。</p>';}else{shown=searchCodes(search.value);$('#libraryStats').textContent=`${CODE_LIBRARY.length} curated clauses · ${shown.length} matches / 条已整理条款 · 条匹配`;results.innerHTML=shown.map((r,i)=>`<button class="library-result" data-code-index="${i}"><span>SCDF §${esc(r.clause)} · ${r.status==='screened'?'INPUT CHECK / 参数筛查':'REVIEW CANDIDATE / 待核实'}</span><strong>${esc(r.title.en)}<small>${esc(r.title.zh)}</small></strong><p>${esc(r.summary.en)}</p></button>`).join('')||'<p class="library-loading">No matching clause / 未找到匹配条款</p>';}[...results.querySelectorAll('[data-code-index]')].forEach(b=>b.onclick=()=>choose(shown[Number(b.dataset.codeIndex)]));if(shown[0])choose(shown[0]);else preview.innerHTML='<p class="library-loading">Choose another search / 请更换关键词</p>';}catch(error){if(token===sequence){results.innerHTML='<p class="library-loading">Local index is loading or unavailable. Retry in a moment.<br>本地索引正在加载或暂不可用，请稍后重试。</p>';$('#libraryStats').textContent=String(error.message).slice(0,120);}}}
 $('#libraryBtn').onclick=()=>{dialog.showModal();run();};$('#libraryClose').onclick=()=>dialog.close();search.oninput=()=>{clearTimeout(timer);timer=setTimeout(run,180);};$('#libraryAgency').onchange=run;
 [...document.querySelectorAll('[data-library-mode]')].forEach(b=>b.onclick=()=>{mode=b.dataset.libraryMode;[...document.querySelectorAll('[data-library-mode]')].forEach(x=>x.classList.toggle('active',x===b));$('#libraryAgency').hidden=mode!=='local';search.value='';run();});
 [...document.querySelectorAll('[data-code-query]')].forEach(b=>b.onclick=()=>{search.value=b.dataset.codeQuery;run();});
 loadLocalCodes().then(data=>{const docs=data.documents||data.index?.documents||[];if(docs.length)$('#libraryBtnCount').textContent=docs.length+' PDFs';}).catch(()=>{});
}
